#pragma once
#include <winhttp.h>
#include <wincred.h>
#include <bcrypt.h>
#include <wincrypt.h>
#include "connector_json.hpp"
namespace ConnectorNet {
static void utf8(const wchar_t* value,char* out,int capacity){if(!WideCharToMultiByte(CP_UTF8,0,value,-1,out,capacity,0,0))out[0]=0;}
static void wide(const char* value,wchar_t* out,int capacity){int bytes=0,units=0;while(value[bytes]&&units<capacity-1){unsigned char c=value[bytes];int width=c<128?1:c>=194&&c<224?2:c<240&&c>=224?3:c>=240&&c<=244?4:1;bool complete=true;for(int n=1;n<width;n++)if(!value[bytes+n]||((BYTE)value[bytes+n]&192)!=128){complete=false;break;}if(!complete)break;int n=width==4?2:1;if(units+n>=capacity)break;bytes+=width;units+=n;}int written=bytes?MultiByteToWideChar(CP_UTF8,0,value,bytes,out,capacity-1):0;out[written]=0;}
static bool encode(const char* text,char* output,size_t capacity){size_t at=0;const char hex[]="0123456789ABCDEF";for(size_t i=0;text[i];i++){unsigned char c=text[i];bool plain=c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||strchr("-_.~",c);size_t need=plain?1:3;if(at+need>=capacity)return false;if(plain)output[at++]=c;else{output[at++]='%';output[at++]=hex[c>>4];output[at++]=hex[c&15];}}output[at]=0;return true;}
static bool decode(const char* text,int length,char* output,int capacity){int at=0;for(int i=0;i<length;i++){unsigned char value=text[i];if(value=='%'){if(i+2>=length||!ConnectorJson::Document::hex(text[i+1])||!ConnectorJson::Document::hex(text[i+2]))return false;auto digit=[](char c){return c<='9'?c-'0':(c|32)-'a'+10;};value=(unsigned char)(digit(text[i+1])*16+digit(text[i+2]));i+=2;}else if(value=='+')value=' ';if(!value||at>=capacity-1)return false;output[at++]=value;}output[at]=0;return true;}
static bool query(const char* query,const char* name,char* output,int capacity){int matches=0;for(const char* field=query;*field;){const char* end=strchr(field,'&');if(!end)end=field+strlen(field);const char* eq=(const char*)memchr(field,'=',end-field);if(eq&&eq-field==(int)strlen(name)&&!memcmp(field,name,strlen(name))){if(!decode(eq+1,(int)(end-eq-1),output,capacity))return false;matches++;}field=*end?end+1:end;}return matches==1;}
static bool sameSecret(const char* a,const char* b){size_t length=strlen(a);if(length!=strlen(b))return false;BYTE diff=0;for(size_t i=0;i<length;i++)diff|=a[i]^b[i];return diff==0;}
static bool base64url(const BYTE* value,DWORD length,char* output,DWORD capacity){DWORD size=capacity;if(!CryptBinaryToStringA(value,length,CRYPT_STRING_BASE64|CRYPT_STRING_NOCRLF,output,&size))return false;for(DWORD i=0;output[i];i++){if(output[i]=='+')output[i]='-';else if(output[i]=='/')output[i]='_';else if(output[i]=='='){output[i]=0;break;}}return true;}
static bool randomToken(char* output,DWORD capacity){BYTE random[32];if(BCryptGenRandom(0,random,sizeof(random),BCRYPT_USE_SYSTEM_PREFERRED_RNG)<0)return false;bool ok=base64url(random,sizeof(random),output,capacity);SecureZeroMemory(random,sizeof(random));return ok;}
static bool challenge(const char* verifier,char* output,DWORD capacity){BCRYPT_ALG_HANDLE alg=0;BCRYPT_HASH_HANDLE hash=0;BYTE digest[32];bool ok=false;if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,0,0)>=0){if(BCryptCreateHash(alg,&hash,0,0,0,0,0)>=0){if(BCryptHashData(hash,(BYTE*)verifier,(ULONG)strlen(verifier),0)>=0&&BCryptFinishHash(hash,digest,sizeof(digest),0)>=0)ok=base64url(digest,sizeof(digest),output,capacity);BCryptDestroyHash(hash);}BCryptCloseAlgorithmProvider(alg,0);}SecureZeroMemory(digest,sizeof(digest));return ok;}
struct Response {DWORD status=0;char* body=0;~Response(){if(body){SecureZeroMemory(body,strlen(body));HeapFree(GetProcessHeap(),0,body);}}};
static bool request(const wchar_t* host,const wchar_t* path,const wchar_t* method,const char* body,const char* bearer,Response& result,HANDLE stop,const wchar_t* contentType=L"application/x-www-form-urlencoded"){
    HINTERNET session=WinHttpOpen(L"BezelBrew/1.0",WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,0,0,0);if(!session)return false;WinHttpSetTimeouts(session,2500,2500,2500,2500);HINTERNET connection=WinHttpConnect(session,host,INTERNET_DEFAULT_HTTPS_PORT,0),req=connection?WinHttpOpenRequest(connection,method,path,0,0,0,WINHTTP_FLAG_SECURE):0;bool ok=false;
    if(req){DWORD redirects=WINHTTP_OPTION_REDIRECT_POLICY_NEVER;WinHttpSetOption(req,WINHTTP_OPTION_REDIRECT_POLICY,&redirects,sizeof(redirects));DWORD disable=WINHTTP_DISABLE_COOKIES;WinHttpSetOption(req,WINHTTP_OPTION_DISABLE_FEATURE,&disable,sizeof(disable));wchar_t headers[9000]=L"Accept: application/json\r\n";if(body){wcscat_s(headers,L"Content-Type: ");wcscat_s(headers,contentType);wcscat_s(headers,L"\r\n");}if(bearer&&bearer[0]){bool safe=true;for(int i=0;bearer[i];i++)if((unsigned char)bearer[i]<33||(unsigned char)bearer[i]>126)safe=false;if(!safe){WinHttpCloseHandle(req);WinHttpCloseHandle(connection);WinHttpCloseHandle(session);return false;}wchar_t token[8192];wide(bearer,token,8192);wcscat_s(headers,L"Authorization: Bearer ");wcscat_s(headers,token);wcscat_s(headers,L"\r\n");SecureZeroMemory(token,sizeof(token));}
        if(WinHttpSendRequest(req,headers,-1,body?(void*)body:0,body?(DWORD)strlen(body):0,body?(DWORD)strlen(body):0,0)&&WinHttpReceiveResponse(req,0)){DWORD size=sizeof(result.status);WinHttpQueryHeaders(req,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,0,&result.status,&size,0);result.body=(char*)HeapAlloc(GetProcessHeap(),HEAP_ZERO_MEMORY,262145);if(result.body){DWORD used=0;ULONGLONG deadline=GetTickCount64()+8000;ok=true;for(;;){if((stop&&WaitForSingleObject(stop,0)==WAIT_OBJECT_0)||GetTickCount64()>deadline){ok=false;break;}DWORD available=0;if(!WinHttpQueryDataAvailable(req,&available)){ok=false;break;}if(!available)break;if(available>262144-used){ok=false;break;}DWORD read=0;if(!WinHttpReadData(req,result.body+used,available,&read)||!read){ok=false;break;}used+=read;}result.body[used]=0;}}
        SecureZeroMemory(headers,sizeof(headers));WinHttpCloseHandle(req);
    }if(connection)WinHttpCloseHandle(connection);WinHttpCloseHandle(session);return ok;
}
static void credentialName(const wchar_t* profile,const wchar_t* kind,wchar_t* output,int capacity){char value[MAX_PATH*4],hash[100];utf8(profile,value,sizeof(value));if(!challenge(value,hash,sizeof(hash)))strcpy_s(hash,"profile");wchar_t id[100];wide(hash,id,100);swprintf_s(output,capacity,L"WinPixel/Gmail/%s/%s",id,kind);}
static bool readCredential(const wchar_t* name,char* output,int capacity){output[0]=0;PCREDENTIAL value=0;if(!CredRead(name,CRED_TYPE_GENERIC,0,&value))return false;bool ok=value->CredentialBlobSize<(DWORD)capacity;if(ok){memcpy(output,value->CredentialBlob,value->CredentialBlobSize);output[value->CredentialBlobSize]=0;}CredFree(value);return ok;}
static bool writeCredential(const wchar_t* name,const char* value,const wchar_t* user=L"BezelBrew Gmail"){CREDENTIAL entry={};entry.Type=CRED_TYPE_GENERIC;entry.TargetName=(wchar_t*)name;entry.CredentialBlob=(BYTE*)value;entry.CredentialBlobSize=(DWORD)strlen(value);entry.Persist=CRED_PERSIST_LOCAL_MACHINE;entry.UserName=(wchar_t*)user;return CredWrite(&entry,0)!=FALSE;}
}
